.darma-loader-tw-badge-pulse { position: relative; display: inline-flex; align-items: center; width: var(--loader-size, 140px); padding: calc(var(--loader-size, 140px) * .09) calc(var(--loader-size, 140px) * .14); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #6366f1) 15%, transparent); box-sizing: border-box; }
.darma-loader-tw-badge-pulse .darma-loader-tw-badge-pulse__bar { flex: 1; height: calc(var(--loader-size, 140px) * .07); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #6366f1) 55%, transparent); }
.darma-loader-tw-badge-pulse .darma-loader-tw-badge-pulse__dot { position: absolute; top: calc(var(--loader-size, 140px) * -.04); right: calc(var(--loader-size, 140px) * -.04); width: calc(var(--loader-size, 140px) * .16); height: calc(var(--loader-size, 140px) * .16); border-radius: 9999px; background: var(--loader-secondary-color, #f43f5e); animation: darma-loader-tw-badge-pulse-twPingDot calc(var(--loader-speed, 1s) * 1.4) cubic-bezier(0, 0, .2, 1) infinite; }
@keyframes darma-loader-tw-badge-pulse-twPingDot { 0% { box-shadow: 0 0 0 0 var(--loader-secondary-color, #f43f5e); } 70%, 100% { box-shadow: 0 0 0 calc(var(--loader-size, 140px) * .14) transparent; } }

